#include <cstdio>
#include <vector>
#include <queue>

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    std::vector<std::vector<int>> g(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        g[u].push_back(v);
        g[v].push_back(u);
    }

    std::vector<int> color(n + 1, -1);
    bool ok = true;
    for (int st = 1; st <= n && ok; ++st) {
        if (color[st] != -1) continue;        // 已属于某个分量
        color[st] = 0;
        std::queue<int> q;
        q.push(st);
        while (!q.empty() && ok) {
            int u = q.front(); q.pop();
            for (int v : g[u]) {
                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;   // 异色
                    q.push(v);
                } else if (color[v] == color[u]) {
                    ok = false; break;         // 同色冲突
                }
            }
        }
    }
    printf("%s\n", ok ? "YES" : "NO");
    return 0;
}
